class Solution {
public:
    vector<vector<int>> adj;
    int dfs(int node,vector<int> &informTime)
    {
        int time=0;
        for(auto it:adj[node])
            time=max(time,dfs(it,informTime));
        return time+informTime[node];
    }
    int numOfMinutes(int n, int headID, vector<int>& manager, vector<int>& informTime) {
        adj.resize(n);
        for(int i=0;i<manager.size();i++)
        {
            if(manager[i]!=-1)
                adj[manager[i]].push_back(i);
        }
        return dfs(headID,informTime);
    }
};

class Solution(object):
    def numOfMinutes(self, n, headID, manager, informTime):
        """
        :type n: int
        :type headID: int
        :type manager: List[int]
        :type informTime: List[int]
        :rtype: int
        """
        self.ans = 0
        g = collections.defaultdict(list)
        for i in range(n):
            if manager[i] != -1:
                g[manager[i]].append(i)

        def dfs(cur_id, cur_time):
            if informTime[cur_id] == 0:
                self.ans = max(self.ans, cur_time)
                return
            for new_id in g[cur_id]:
                dfs(new_id, cur_time + informTime[cur_id])

        dfs(headID, 0)
        return self.ans
